class Solution:
    def carFleet(self, target: int, position: list[int], speed: list[int]) -> int:
        fleets = 0
        slowest_time_ahead = 0.0
        for p, s in sorted(zip(position, speed), reverse=True):
            time = (target - p) / s
            if time > slowest_time_ahead:
                fleets += 1
                slowest_time_ahead = time
        return fleets

